def _total_weight(edges, weight_by_edge):
    return sum(weight_by_edge[e] for e in edges)


def _connected_components(edges):
    """Return the set of frozensets representing connected components of the graph formed by edges."""
    adjacency = {}
    for u, v in edges:
        adjacency.setdefault(u, set()).add(v)
        adjacency.setdefault(v, set()).add(u)
    seen = set()
    components = []
    for node in adjacency:
        if node in seen:
            continue
        stack = [node]
        comp = set()
        while stack:
            cur = stack.pop()
            if cur in comp:
                continue
            comp.add(cur)
            seen.add(cur)
            for nxt in adjacency[cur]:
                if nxt not in comp:
                    stack.append(nxt)
        components.append(frozenset(comp))
    return components


