    b = Node("B")
    c = Node("C")
    d = Node("D")
    a.outgoing_nodes = {b, c}
    b.incoming_nodes = {a}
    b.outgoing_nodes = {d}
    c.incoming_nodes = {a}
    c.outgoing_nodes = {d}
    d.incoming_nodes = {b, c}
    return a, b, c, d


def _assert_valid_topological_order(ordered, nodes):
    """校验返回结果满足拓扑序后置条件。"""
    assert len(ordered) == len(nodes)
    assert set(ordered) == set(nodes)
    assert len(ordered) == len(set(ordered))
    position = {node: idx for idx, node in enumerate(ordered)}
    for node in nodes:
        for nextnode in node.outgoing_nodes:
            assert position[node] < position[nextnode]


